CREATE TABLE `IntegrationCredential` (`id` varchar(191) NOT NULL, `organizationId` varchar(191) NOT NULL, `provider` enum('YOUTUBE','SPOTIFY') NOT NULL, `credentialsEncrypted` text NOT NULL, `active` boolean NOT NULL DEFAULT true, `lastTestedAt` datetime(3) NULL, `lastTestError` text NULL, `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` datetime(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `IntegrationCredential_organizationId_provider_key` (`organizationId`,`provider`), KEY `IntegrationCredential_organizationId_active_idx` (`organizationId`,`active`), CONSTRAINT `IntegrationCredential_organizationId_fkey` FOREIGN KEY (`organizationId`) REFERENCES `Organization`(`id`) ON DELETE CASCADE ON UPDATE CASCADE);
